const buildDr=()=>DR.map((s,i)=>({label:`DP QROC ${i+1} · ${s.title}`,allowed_voies:["externe"],vignette:s.vignette,questions:s.questions}));


function validateSourceBlocks(extract,content){
 const valid=new Set((extract.blocs||[]).filter(b=>b.id).map(b=>b.id));
 const visit=v=>{if(!v||typeof v!=="object")return;if(Array.isArray(v)){v.forEach(visit);return;}if(v.sourceBlocks)for(const id of v.sourceBlocks)if(!valid.has(id))throw new Error(`sourceBlock absent: ${id}`);Object.values(v).forEach(visit);};
 visit(content);
}
export function buildChapter35(extract){const fiche=buildFiche(),flashcards=buildFlashcards(),series=[...buildIq(),...buildDq(),...buildIr(),...buildDr()];const result={fiche,flashcards,series};validateSourceBlocks(extract,result);return result;}
export default buildChapter35;
